    r"^- (?:\[(?P<id>d-[\w-]+)\] )?\[(?P<ts>T[+-]\d{2,}:\d{2})\] (?P<body>.+?) — (?P<who>[^—]+?) — (?P<reason>.*?)"
    r"(?: — supersedes \[(?P<supersedes>[^\]]+)\])?(?: — promotes \[(?P<promotes>[^\]]+)\])?$"
)
